function savedata(Filename, Header, trialData, Metadataname, Metadata)
% Basically generated by ChatGPT but it works
% SAVEDATA Save one trial of behavioral data to CSV and experiment metadata to TXT.
%
% Filename     - behavioral CSV file path
% Header       - cell array containing CSV column names
% trialData    - numeric vector containing one trial's data'
% Metadataname - metadata TXT file path
% Metadata     - metadata text
%
% The metadata file is created once; the CSV header is created once;
% every call appends one row of trial data.

    % Validate inputs before touching output files.
    if ~iscell(Header) || isempty(Header)
        error('savedata:InvalidHeader', 'Header must be a non-empty cell array.');
    end
    if ~isnumeric(trialData) || ~isvector(trialData)
        error('savedata:InvalidTrialData', 'trialData must be a numeric vector.');
    end
    if numel(trialData) ~= numel(Header)
        error('savedata:ColumnCountMismatch', ...
            'Header has %d columns, but trialData has %d values.', ...
            numel(Header), numel(trialData));
    end

    % Ensure destination folders exist.
    ensureParentFolder(Filename);
    ensureParentFolder(Metadataname);

    % 1) Write metadata independently of behavioral-data saving.
    metadataInfo = dir(Metadataname);
    metadataIsEmpty = isempty(metadataInfo) || metadataInfo(1).bytes == 0;
    if ~isfile(Metadataname) || metadataIsEmpty
        fidMeta = fopen(Metadataname, 'w');
        if fidMeta == -1
            error('savedata:MetadataOpenFailed', ...
                'Cannot create metadata file: %s', Metadataname);
        end
        metaCleanup = onCleanup(@() fcloseIfOpen(fidMeta)); %#ok<NASGU>

        if isstring(Metadata)
            Metadata = char(Metadata);
        end
        if ~ischar(Metadata)
            error('savedata:InvalidMetadata', 'Metadata must be a character vector or string.');
        end
        fprintf(fidMeta, '%s', Metadata);
        if isempty(Metadata) || Metadata(end) ~= newline
            fprintf(fidMeta, '\n');
        end
        fclose(fidMeta);
        clear metaCleanup
    end

    % 2) Create the CSV header if the file is missing or empty.
    csvInfo = dir(Filename);
    csvIsEmpty = isempty(csvInfo) || csvInfo(1).bytes == 0;
    if ~isfile(Filename) || csvIsEmpty
        fidHeader = fopen(Filename, 'w');
        if fidHeader == -1
            error('savedata:CSVOpenFailed', ...
                'Cannot create behavioral CSV file: %s', Filename);
        end
        headerCleanup = onCleanup(@() fcloseIfOpen(fidHeader)); %#ok<NASGU>

        for i = 1:numel(Header)
            if i > 1
                fprintf(fidHeader, ',');
            end
            fprintf(fidHeader, '%s', char(string(Header{i})));
        end
        fprintf(fidHeader, '\n');
        fclose(fidHeader);
        clear headerCleanup
    end

    % 3) Append one trial row on EVERY call, regardless of metadata-file state.
    fidData = fopen(Filename, 'a');
    if fidData == -1
        error('savedata:CSVAppendFailed', ...
            'Cannot open behavioral CSV file for appending: %s', Filename);
    end
    dataCleanup = onCleanup(@() fcloseIfOpen(fidData)); %#ok<NASGU>

    trialData = trialData(:).';%'
    for i = 1:numel(trialData)
        if i > 1
            fprintf(fidData, ',');
        end
        value = trialData(i);
        if isnan(value)
            fprintf(fidData, 'NaN');
        elseif isinf(value)
            if value > 0
                fprintf(fidData, 'Inf');
            else
                fprintf(fidData, '-Inf');
            end
        else
            fprintf(fidData, '%.15g', value);
        end
    end
    fprintf(fidData, '\n');
    fclose(fidData);
    clear dataCleanup
end

function ensureParentFolder(filePath)
    parentFolder = fileparts(filePath);
    if ~isempty(parentFolder) && ~isfolder(parentFolder)
        [ok, message] = mkdir(parentFolder);
        if ~ok
            error('savedata:FolderCreateFailed', ...
                'Cannot create folder "%s": %s', parentFolder, message);
        end
    end
end

function fcloseIfOpen(fid)
    if isnumeric(fid) && isscalar(fid) && fid >= 0
        try
            fclose(fid);
        catch
        end
    end
end
